import{_ as e,c as a,o,ae as r}from"./chunks/framework.Bi6zybwU.js";const m=JSON.parse('{"title":"Construct Table from CSV","description":"Construct Table from CSV","frontmatter":{"title":"Construct Table from CSV","description":"Construct Table from CSV"},"headers":[],"relativePath":"guide/data-sources/construct-table-from-csv.md","filePath":"guide/data-sources/construct-table-from-csv.md"}'),s={name:"guide/data-sources/construct-table-from-csv.md"};function n(l,t,c,i,u,d){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="construct-table-from-csv" tabindex="-1">Construct Table from CSV <a class="header-anchor" href="#construct-table-from-csv" aria-label="Permalink to &quot;Construct Table from CSV&quot;">​</a></h1><p>Other than Google Sheets, if you wish to show data form from another source and if this source shares data with the web as a .CSV (Comma Separated Value), then we can use external data source links to create a table. Let&#39;s dive into this simple article to learn how to construct a table from CSV. Construct Table From External CSV is a Pro Feature.</p><ul><li>Click &quot;Add Table&quot; and pick the <strong>Connect External CSV</strong> from the initial sidebar menu.</li><li>Name the table. It&#39;ll be your table title &amp; paste your External Data Source Link in the <strong>Data Source URL</strong> field.</li><li>Once you’re done, proceed to the <strong>Next</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2022/10/Construct-Table-From-CSV-1-scaled.webp" alt=""></li><li>Choose and save the entry fields you wish to add.</li></ul><p>This is how all your data will be imported here automatically. Lastly, don&#39;t forget to click on the <strong>Save</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2022/10/Construct-Table-From-CSV-2-scaled.webp" alt=""></p><ul><li>The table has been created here (See the below screenshot) <img src="https://ninjatables.com/wp-content/uploads/2022/10/Construct-Table-From-CSV-3-scaled.webp" alt=""> All other settings are exactly the same as Google Sheets. Please check the <strong><a href="https://ninjatables.com/docs/google-sheets-integration/" target="_blank" rel="noreferrer">documentation</a></strong> for further details. Creating data tables from CSV as an external source is fast and easy in Ninja Tables. If you already have tables in another website, simply fetch the table using CSV.</li></ul>',5)])])}const b=e(s,[["render",n]]);export{m as __pageData,b as default};
